chart_violin = img_to_base64('/app/output/chart_violin.png')
chart_spread = img_to_base64('/app/output/chart_spread.png')
chart_lag = img_to_base64('/app/output/chart_lag.png')
chart_coverage = img_to_base64('/app/output/chart_coverage.png')
chart_station_fuels = img_to_base64('/app/output/chart_station_fuels.png')

